/**
 * 苏住房防汛（service-expand / com.zhishu.flood）后端联调脚本
 *
 * 覆盖 service-expand 模块下 flood 包的 7 个 Controller：
 *   FloodCommonController       /v2.0/safety/flood/common/*
 *   FloodEventController        /v2.0/safety/flood/event/*
 *   FloodEventChangeController  /v2.0/safety/flood/eventChange/*
 *   FloodPlanController         /v2.0/safety/flood/plan/*
 *   FloodInspectionController   /v2.0/safety/flood/inspection/*
 *   FloodRescueController       /v2.0/safety/flood/rescue/*
 *   FloodCauseController        /v2.0/safety/flood/cause/*
 *
 * 用法：
 *   set INTEGRATION_PASSWORD=xxx
 *   node artifacts/flood-integration.mjs            # 全量探测
 *   node artifacts/flood-integration.mjs <关键字>   # 只测匹配的接口
 *
 * 输出：每个接口一行，标注 HTTP 状态 + code + 业务含义，最后汇总统计。
 */
import crypto from 'node:crypto'
import { writeFileSync, mkdirSync } from 'node:fs'

const FRAMEWORK_BASE = 'http://127.0.0.1:9211'
const EXPAND_BASE = 'http://127.0.0.1:9610'
const PROJECT_ID = '1'
const AES_KEY = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal', 'utf8')
const AES_IV = Buffer.from('A-16-Byte-String', 'utf8')

function encryptPassword(plain) {
  const cipher = crypto.createCipheriv('aes-256-cbc', AES_KEY, AES_IV)
  return Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]).toString('base64')
}

async function call(method, url, { body, token } = {}) {
  const headers = { 'zhi-project-id': PROJECT_ID }
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  if (token) headers.Authorization = `Bearer ${token}`
  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  const text = await res.text()
  let json = null
  try { json = JSON.parse(text) } catch { /* 非 JSON 原样保留 */ }
  return { status: res.status, json, text }
}

async function login() {
  const password = process.env.INTEGRATION_PASSWORD
  if (!password) throw new Error('缺少环境变量 INTEGRATION_PASSWORD')
  const { status, json } = await call('POST', `${FRAMEWORK_BASE}/v2.0/security/auth/login`, {
    body: { username: 'zsbase', password: encryptPassword(password) },
  })
  if (!json || !json.data || !json.data.accessToken) {
    throw new Error(`登录失败 HTTP ${status}: ${JSON.stringify(json).slice(0, 300)}`)
  }
  return json.data.accessToken
}

/** 把响应概括成一行人话 */
function summarize(r) {
  if (r.status >= 400) return `HTTP ${r.status} ${(r.text || '').replace(/\s+/g, ' ').slice(0, 120)}`
  const j = r.json
  if (!j) return `HTTP ${r.status} 非JSON ${(r.text || '').slice(0, 100)}`
  const code = j.code ?? '?'
  const msg = j.msg ?? ''
  if (j.total !== undefined) return `code=${code} "${msg}" total=${j.total} rows=${Array.isArray(j.rows) ? j.rows.length : '?'}`
  if (j.data !== undefined) {
    const d = j.data
    if (Array.isArray(d)) return `code=${code} "${msg}" data[${d.length}]`
    if (d && typeof d === 'object') return `code=${code} "${msg}" data{${Object.keys(d).slice(0, 6).join(',')}}`
    return `code=${code} "${msg}" data=${d}`
  }
  if (Array.isArray(j)) return `code=? 裸数组[${j.length}]`
  return `code=${code} "${msg}"`
}

/** 判定是否成功：com.zhishu 约定 code===200 为成功 */
function verdict(r) {
  if (r.status >= 500) return 'FAIL'
  if (r.status >= 400) return 'WARN'
  const c = r.json?.code
  if (c === 200 || c === 0 || c === undefined) return 'OK'
  return 'BIZ'
}

async function main() {
  const filter = process.argv[2] || ''
  console.log('=== 登录 common-framework(9211) ===')
  const token = await login()
  console.log(`  token 获取成功 ${token.slice(0, 20)}...\n`)

  // 先取一些真实 id，后续接口需要
  console.log('=== 采集真实基础数据 id ===')
  const pageRes = await call('GET', `${EXPAND_BASE}/v2.0/safety/flood/event/page?pageNum=1&pageSize=1`, { token })
  console.log(`  event/page -> ${summarize(pageRes)}`)
  const firstEvent = pageRes.json?.rows?.[0] ?? pageRes.json?.data?.rows?.[0] ?? null
  const eventId = firstEvent?.eventId ?? firstEvent?.id ?? null
  const complexId = firstEvent?.complexId ?? null
  console.log(`  取到 eventId=${eventId} complexId=${complexId}\n`)

  // ---- 接口清单 ----
  const cases = [
    // 通用字典
    ['common', 'GET', '/v2.0/safety/flood/common/area', {}],
    ['common', 'GET', '/v2.0/safety/flood/common/complex', {}],
    ['common', 'GET', '/v2.0/safety/flood/common/dict', {}],
    ['common', 'GET', '/v2.0/safety/flood/common/dict/eventType', {}],
    ['common', 'GET', '/v2.0/safety/flood/common/dict/level', {}],
    ['common', 'GET', '/v2.0/safety/flood/common/dict/status', {}],
    // 事件
    ['event', 'GET', '/v2.0/safety/flood/event/page?pageNum=1&pageSize=10', {}],
    ['event', 'GET', '/v2.0/safety/flood/event/list', {}],
    ['event', 'GET', '/v2.0/safety/flood/event/statistics', {}],
    ['event', 'GET', `/v2.0/safety/flood/event/${eventId ?? 1}`, {}],
    ['event', 'GET', '/v2.0/safety/flood/event/current', {}],
    // 事件变更
    ['eventChange', 'GET', '/v2.0/safety/flood/eventChange/page?pageNum=1&pageSize=10', {}],
    ['eventChange', 'GET', '/v2.0/safety/flood/eventChange/list', {}],
    ['eventChange', 'GET', `/v2.0/safety/flood/eventChange/${eventId ?? 1}`, {}],
    // 预案
    ['plan', 'GET', '/v2.0/safety/flood/plan/page?pageNum=1&pageSize=10', {}],
    ['plan', 'GET', '/v2.0/safety/flood/plan/list', {}],
    ['plan', 'GET', `/v2.0/safety/flood/plan/${eventId ?? 1}`, {}],
    // 巡检
    ['inspection', 'GET', '/v2.0/safety/flood/inspection/page?pageNum=1&pageSize=10', {}],
    ['inspection', 'GET', `/v2.0/safety/flood/inspection/${eventId ?? 1}`, {}],
    ['inspection', 'GET', `/v2.0/safety/flood/inspection/template?eventId=${eventId ?? 1}`, {}],
    ['inspection', 'GET', `/v2.0/safety/flood/inspection/last?complexId=${complexId ?? 1}`, {}],
    ['inspection', 'GET', `/v2.0/safety/flood/inspection/summary?eventId=${eventId ?? 1}`, {}],
    // 抢险
    ['rescue', 'GET', '/v2.0/safety/flood/rescue/page?pageNum=1&pageSize=10', {}],
    ['rescue', 'GET', '/v2.0/safety/flood/rescue/list', {}],
    // 隐患
    ['cause', 'GET', '/v2.0/safety/flood/cause/page?pageNum=1&pageSize=10', {}],
    ['cause', 'GET', '/v2.0/safety/flood/cause/list', {}],
    ['cause', 'GET', '/v2.0/safety/flood/cause/statistics', {}],
  ]

  const picked = filter ? cases.filter(c => c[0].includes(filter) || c[2].includes(filter)) : cases
  console.log(`=== 开始探测 ${picked.length} 个接口 ===`)
  const results = []
  for (const [group, method, path, opts] of picked) {
    let r
    try {
      r = await call(method, EXPAND_BASE + path, { token, ...opts })
    } catch (e) {
      r = { status: 0, json: null, text: String(e) }
    }
    const v = verdict(r)
    const line = `${v.padEnd(4)} ${group.padEnd(12)} ${method} ${path}`
    console.log(`${line}\n       -> ${summarize(r)}`)
    results.push({ group, method, path, verdict: v, status: r.status, summary: summarize(r), body: r.json })
  }

  // ---- 汇总 ----
  console.log('\n=== 汇总 ===')
  const byVerdict = results.reduce((a, r) => (a[r.verdict] = (a[r.verdict] || 0) + 1, a), {})
  console.log('  ' + Object.entries(byVerdict).map(([k, v]) => `${k}=${v}`).join('  '))

  mkdirSync('artifacts', { recursive: true })
  writeFileSync('artifacts/flood-integration-report.json', JSON.stringify(results, null, 2), 'utf8')
  console.log('  明细已写入 artifacts/flood-integration-report.json')
}

main().catch(e => { console.error('联调脚本异常:', e.message); process.exit(1) })

