const AES_KEY = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal', 'utf8')
const AES_IV = Buffer.from('A-16-Byte-String', 'utf8')

function encryptPassword(plain) {
  const cipher = crypto.createCipheriv('aes-256-cbc', AES_KEY, AES_IV)
  return Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]).toString('base64')
}

async function call(method, url, { body, token } = {}) {
  const headers = { 'zhi-project-id': PROJECT_ID }
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  if (token) headers.Authorization = `Bearer ${token}`
  const res = await fetch(url, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) })
  const text = await res.text()
  let json = null
  try { json = JSON.parse(text) } catch { /* 保留原文 */ }
  return { status: res.status, json, text }
}

async function login() {
  const password = process.env.INTEGRATION_PASSWORD
  if (!password) throw new Error('缺少环境变量 INTEGRATION_PASSWORD')
  const { status, json } = await call('POST', `${FRAMEWORK_BASE}/v2.0/security/auth/login`, {
    body: { username: 'zsbase', password: encryptPassword(password) },
  })
  if (!json?.data?.accessToken) throw new Error(`登录失败 HTTP ${status}: ${JSON.stringify(json).slice(0, 300)}`)
  return json.data.accessToken
}

function summarize(r) {
  if (r.status >= 400) return `HTTP ${r.status} ${(r.text || '').replace(/\s+/g, ' ').slice(0, 130)}`
  const j = r.json
  if (!j) return `HTTP ${r.status} 非JSON: ${(r.text || '').slice(0, 110)}`
  const code = j.code ?? '?'
  const msg = j.msg ?? ''
  if (j.total !== undefined) {
    const rows = Array.isArray(j.rows) ? j.rows : []
    const first = rows[0] ? Object.keys(rows[0]).slice(0, 5).join(',') : ''
    return `code=${code} "${msg}" total=${j.total} rows=${rows.length}${first ? ' 字段[' + first + '...]' : ''}`
  }
  if (j.data !== undefined) {
    const d = j.data
    if (Array.isArray(d)) {
      const k = d[0] ? Object.keys(d[0]).slice(0, 5).join(',') : ''
      return `code=${code} "${msg}" 数组[${d.length}]${k ? ' 字段[' + k + '...]' : ''}`
    }
    if (d && typeof d === 'object') return `code=${code} "${msg}" 对象{${Object.keys(d).slice(0, 7).join(',')}}`
    return `code=${code} "${msg}" data=${d}`
  }
  return `code=${code} "${msg}"`
}

/** com.zhishu 约定：code===200 成功；HTTP>=500 视为服务异常 */
function verdict(r) {
