[{"type":"text","text":"package com.zhishu.common.feign.interceptor;

import cn.hutool.core.util.ObjectUtil;
import cn.hutool.core.util.StrUtil;
import com.zhishu.common.core.constant.RequestHeaders;
import com.zhishu.common.core.constant.SecurityConstants;
import com.zhishu.common.web.utils.IpUtils;
import com.zhishu.common.web.utils.ServletUtils;
import feign.RequestInterceptor;
import feign.RequestTemplate;

import javax.servlet.http.HttpServletRequest;
import java.util.Map;

/**
 * feign 请求拦截器
 *
 * @author ruoyi
 */
public class FeignRequestInterceptor implements RequestInterceptor {

    @Override
    public void apply(RequestTemplate requestTemplate) {
        HttpServletRequest httpServletRequest = ServletUtils.getRequest();
        if (ObjectUtil.isNotNull(httpServletRequest)) {
            Map<String, String> headers = ServletUtils.getHeaders(httpServletRequest);
            // 传递用户信息请求头，防止丢失
            String userId = headers.get(SecurityConstants.USER_ID_KEY);
            if (StrUtil.isNotEmpty(userId)) {
                requestTemplate.header(SecurityConstants.USER_ID_KEY, userId);
            }
            String userName = headers.get(SecurityConstants.USER_NAME_KEY);
            if (StrUtil.isNotEmpty(userName)) {
                requestTemplate.header(SecurityConstants.USER_NAME_KEY, userName);
            }
            String authentication = headers.get(SecurityConstants.AUTHORIZATION_HEADER);
            if (StrUtil.isNotEmpty(authentication) && !requestTemplate.headers().containsKey(SecurityConstants.AUTHORIZATION_HEADER)) {
                requestTemplate.header(SecurityConstants.AUTHORIZATION_HEADER, authentication);
            }
            String projectId = headers.get(RequestHeaders.ZHI_PROJECT_ID);
            if (StrUtil.isNotEmpty(projectId)) {
                requestTemplate.header(RequestHeaders.ZHI_PROJECT_ID, projectId);
            }
            String gbcType = headers.get(RequestHeaders.GBC_TYPE);
            if (StrUtil.isNotEmpty(gbcType)) {
                requestTemplate.header(RequestHeaders.GBC_TYPE, gbcType);
            }
            String terminalType = headers.get(RequestHeaders.TERMINAL_TYPE);
            if (StrUtil.isNotEmpty(terminalType)) {
                requestTemplate.header(RequestHeaders.TERMINAL_TYPE, terminalType);
            }
            // 内部请求授权
            requestTemplate.header(SecurityConstants.INNER, SecurityConstants.INNER_AUTH_CODE);
            // 配置客户端IP
            requestTemplate.header("X-Forwarded-For" , IpUtils.getIpAddr(ServletUtils.getRequest()));
        }
    }
}
"}]
